Output 0: {"name": "ArchiveResult", "type": "delimited", "fields": [{"name": "archive_id", "type": "integer"}, {"name": "status", "type": "string"}, {"name": "canonical", "type": "string"}, {"name": "site_key", "type": "string"}, {"name": "site_status", "type": "string"}, {"name": "sequence_status", "type": "string"}, {"name": "copy_band", "type": "string"}, {"name": "approved", "type": "boolean"}, {"name": "issues", "type": "integer"}, {"name": "queue", "type": "string"}]}

