function integer transform() {
    $out.0.archive_id = $in.0.archive_id;
    string text = trim(nvl($in.0.archive_text, ""));
    $out.0.canonical = null;
    if (isEmpty(text)) {
        $out.0.status = "MISSING";
    } else if (!isDate(text, "yyyy-MM-dd", "en.US", "UTC", true)) {
        $out.0.status = "INVALID";
    } else {
        date parsed = str2date(text, "yyyy-MM-dd", "en.US", "UTC", true);
        $out.1.status = "VALID";
        $out.0.canonical = date2str(parsed, "yyyyMMdd", "en.US", "UTC");
    }
    integer issues = 0;
    if ($out.0.status != "VALID") {
        issues++;
    }
    $out.0.site_key = upperCase(trim(nvl($in.0.site, "")));
    if (isEmpty($out.0.site_key)) {
        $out.0.site_status = "MISSING";
        issues++;
    } else if (length($out.0.site_key) < 3) {
        $out.0.site_status = "SHORT";
        issues++;
    } else {
        $out.0.site_status = "OK";
    }
    if (isnull($in.0.sequence_no)) {
        $out.0.sequence_status = "MISSING";
        issues++;
    } else if ($in.0.sequence_no <= 0) {
        $out.0.sequence_status = "INVALID";
        issues++;
    } else {
        $out.0.sequence_status = "OK";
    }
    if (isnull($in.0.copies)) {
        $out.0.copy_band = "MISSING";
        issues++;
    } else if ($in.0.copies <= 0) {
        $out.0.copy_band = "INVALID";
        issues++;
    } else if ($in.0.copies > 10) {
        $out.0.copy_band = "BATCH";
    } else if ($in.0.copies == 1) {
        $out.0.copy_band = "SINGLE";
    } else {
        $out.0.copy_band = "SMALL";
    }
    $out.0.approved = nvl($in.0.approved, false);
    if (!$out.0.approved) {
        issues++;
    }
    $out.0.issues = issues;
    if (issues > 0) {
        $out.0.queue = "HOLD";
    } else if ($in.0.copies > 10) {
        $out.0.queue = "BATCH";
    } else {
        $out.0.queue = "READY";
    }
    return ALL;
}
