decimal[] royalty_values = [];
function void post_royalty(string label, decimal value) {
    append(royalty_actions, label);
    append(royalty_values, value);
}
function integer count() {
    royalty_actions = [];
    royalty_values = [];
    royalty_reference = $in.0.external_license_id;
    /* Priority table:
       1. withdrawn license -> 0 rows
       2. negative units -> 1 rows
       3. promotional grant -> 0 rows
       4. chargeback -> 1 rows
       5. audited foreign license -> 3 rows
       6. zero royalty -> 2 rows
       7. foreign license -> 2 rows
       8. domestic license -> 1 rows
    */
    if ($in.0.territory_status == "WITHDRAWN") {
        return 0; // withdrawn license
    }
    else if ($in.0.licensed_units < 0d) {
        post_royalty("ERROR", -$in.0.licensed_units);
        return 1; // negative units
    }
    else if ($in.0.territory_status == "PROMO") {
        return 0; // promotional grant
    }
    else if ($in.0.territory_status == "CHARGEBACK") {
        post_royalty("CHARGEBACK", -$in.0.unit_rate*$in.0.licensed_units);
        return 1; // chargeback
    }
    else if ($in.0.territory_status == "FOREIGN" && $in.0.review) {
        post_royalty("NET", $in.0.unit_rate*$in.0.licensed_units*(100d-25d)/100d);
        post_royalty("WITHHOLD", $in.0.unit_rate*$in.0.licensed_units*25d/100d);
        post_royalty("AUDIT", 0d);
        return 3; // audited foreign license
    }
    else if ($in.0.unit_rate == 0d) {
        post_royalty("ZERO", 0d);
        post_royalty("USAGE", $in.0.licensed_units);
        return 2; // zero royalty
    }
    else if ($in.0.territory_status == "FOREIGN") {
        post_royalty("NET", $in.0.unit_rate*$in.0.licensed_units*(100d-25d)/100d);
        post_royalty("WITHHOLD", $in.0.unit_rate*$in.0.licensed_units*25d/100d);
        return 2; // foreign license
    }
    else if (true) {
        post_royalty("GROSS", $in.0.unit_rate*$in.0.licensed_units);
        return 1; // domestic license
    }
    return 0;
}
