    $out.0.problemss = problems;
    if (problems > 0) {
        $out.0.route = "REVIEW";
    } else if ($in.0.priority >= 7) {
        $out.0.route = "EXPRESS";
    } else {
        $out.0.route = "STANDARD";
    }
    return ALL;
}
