decimal[] escrow_2_amount_rows = [];
date[] escrow_2_pay_on_rows = [];
boolean[] escrow_2_final_payment_rows = [];
long escrow_2_key;
function void stage_escrow_2(string p0, decimal p1, date p2, boolean p3) {
    append(escrow_2_escrow_action_rows, p0);
    append(escrow_2_amount_rows, p1);
    append(escrow_2_pay_on_rows, p2);
    append(escrow_2_final_payment_rows, p3);
}
function integer count() {
    escrow_2_escrow_action_rows = [];
    escrow_2_amount_rows = [];
    escrow_2_pay_on_rows = [];
    escrow_2_final_payment_rows = [];
    escrow_2_source = $in.0.contract_id;
    escrow_2_key = 0L;
    decimal net = $in.0.funding-$in.0.fee;
    /* Branch census:
       1. invalid net funding -> 1 rows
       2. approval unresolved -> 1 rows
       3. approval denied -> 0 rows
       4. not yet due -> 0 rows
       5. reviewed payable release -> 3 rows
       6. ordinary payable release -> 2 rows
    */
    if ($in.0.funding < 0d || $in.0.fee < 0d || net < 0d) {
        escrow_2_key = sequence(Keys_escrow_release, long).next();
        stage_escrow_2("ERROR", 0d, $in.0.requested_on, false);
        return 1; // invalid net funding
