        stage_escrow_2("RETAIN", net*30d/100d, $in.0.due_on, false);
        return 3; // reviewed payable release
    }
    else if (true) {
        escrow_2_key = sequence(Keys_escrow_release, long).next();
        stage_escrow_2("BENEFICIARY", net, $in.0.release_on, true);
        stage_escrow_2("FEE", $in.0.fee, $in.0.requested_on, false);
        return 2; // ordinary payable release
    }
    return 0;
}
function integer transform(integer idx) {
    $out.0.source_contract_id = escrow_2_source;
    $out.0.escrow_action = escrow_2_escrow_action_rows[idx];
    $out.0.amount = escrow_2_amount_rows[idx];
    $out.0.pay_on = escrow_2_pay_on_rows[idx];
    $out.0.final_payment = escrow_2_final_payment_rows[idx];
    $out.0.allocation_key = escrow_2_key;
    return SKIP;
}
