function void stage_time_2(string p0, long p1, date p2, date p3, boolean p4) {
    append(time_2_pay_bucket_rows, p0);
    append(time_2_minutes_rows, p1);
    append(time_2_segment_from_rows, p2);
    append(time_2_segment_to_rows, p3);
    append(time_2_paid_rows, p4);
}
function integer count() {
    time_2_pay_bucket_rows = [];
    time_2_minutes_rows = [];
    time_2_segment_from_rows = [];
    time_2_segment_to_rows = [];
    time_2_paid_rows = [];
    time_2_source = $in.0.sheet_id;
    long duration = 0L;
    if (!isnull($in.0.clock_out)) duration = dateDiff($in.0.clock_out, $in.0.clock_in, minute);
    long pause = nvl($in.0.break_minutes, 0);
    long net = duration-pause;
    /* Branch census:
       1. unfinished attendance -> 1 rows
       2. withdrawn sheet -> 0 rows
       3. backward clock -> 1 rows
       4. approval pending -> 1 rows
       5. training attendance -> 1 rows
       6. three travel segments -> 3 rows
       7. overtime allocation -> 2 rows
       8. reviewed work -> 2 rows
       9. ordinary paid work -> 1 rows
    */
    if ($in.0.clock_out == null) {
        stage_time_2("OPEN", 0L, dateAdd($in.0.clock_in, 0L, minute), null, false);
        return 1; // unfinished attendance
    }
    else if ($in.0.category == "CANCEL") {
        return 0; // withdrawn sheet
    }
    else if (duration < 0L) {
        stage_time_2("ERROR", duration, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, duration, minute), false);
        return 1; // backward clock
    }
    else if (!$in.0.approved) {
        stage_time_2("PENDING", net, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, net, minute), false);
        return 1; // approval pending
    }
    else if ($in.0.category == "TRAIN") {
        stage_time_2("TRAIN", net, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, net, minute), true);
        return 1; // training attendance
    }
    else if ($in.0.category == "TRAVEL" && duration >= 60L) {
        stage_time_2("OUTBOUND", 30L, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, 30L, minute), false);
        stage_time_2("ONSITE", duration-60L, dateAdd($in.0.clock_in, 30L, minute), dateAdd($in.0.clock_in, duration-30L, minute), true);
        stage_time_2("RETURN", 30L, dateAdd($in.0.clock_in, duration-30L, minute), dateAdd($in.0.clock_in, duration, minute), false);
        return 3; // three travel segments
    }
    else if (net > 450L) {
        stage_time_2("REGULAR", 450L, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, 450L, minute), true);
        stage_time_2("OVERTIME", net-450L, dateAdd($in.0.clock_in, 450L, minute), dateAdd($in.0.clock_in, net, minute), true);
        return 2; // overtime allocation
    }
    else if ($in.0.review) {
        stage_time_2("AUDIT", 0L, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, 0L, minute), false);
        stage_time_2("WORK", net, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, net, minute), true);
        return 2; // reviewed work
    }
    else if (true) {
        stage_time_2("WORK", net, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, net, minute), true);
        return 1; // ordinary paid work
    }
    return 0;
}
function integer transform(integer idx) {
    $out.0.source_sheet_id = time_2_source;
