Output 0: {"name": "VialResult", "type": "delimited", "fields": [{"name": "vial_id", "type": "integer"}, {"name": "status", "type": "string"}, {"name": "normalized", "type": "string"}, {"name": "problems", "type": "integer"}, {"name": "route", "type": "string"}, {"name": "quantity_band", "type": "string"}, {"name": "priority_band", "type": "string"}, {"name": "destination_ok", "type": "boolean"}, {"name": "operator_ok", "type": "boolean"}, {"name": "held", "type": "boolean"}]}

