GliderThermalQuality operations: Average known nonnegative vertical speeds, or null if none qualify. Classify their strength and report the total number of input samples, including sinking and missing measurements. Group by flight, sector. Each complete key arrives contiguously; preserve input order.
Input 0:
<Record name="GliderThermalQualityInput" type="delimited"><Field name="flight" type="long" nullable="false"/><Field name="sector" type="string" nullable="false"/><Field name="vertical_speed" type="integer" nullable="true"/></Record>
Output 0:
<Record name="GliderThermalQualityOutput" type="delimited"><Field name="flight" type="long" nullable="false"/><Field name="sector" type="string" nullable="false"/><Field name="mean_lift" type="number" nullable="true"/><Field name="quality" type="string" nullable="true"/><Field name="total_samples" type="integer" nullable="true"/></Record>
Accumulator:
<Record name="GliderThermalQualityState" type="delimited"><Field name="lift" type="number" nullable="true"/><Field name="usable" type="integer" nullable="true"/><Field name="strong" type="integer" nullable="true"/><Field name="samples" type="integer" nullable="true"/><Field name="mean" type="number" nullable="true"/></Record>

```ctl
//#CTL2
function integer thermalClass(integer lift) {
    if (lift < 0) {
        return 0;
    }
    if (lift < 3) {
        return 1;
    }
    if (lift < 8) {
        return 2;
    }
    return 3;
}
function string quality(integer strong, integer usable) {
    if (usable == 0) {
        return "no-thermals";
    }
    if (strong == usable) {
        return "uniformly-strong";
    }
    if (strong == 0) {
        return "weak";
    }
    return "mixed";
}
function boolean finishGroup(GliderThermalQualityState a) {
if (a.usable == 0) {
    a.mean = null;
} else {
    a.mean = a.lift / a.usable;
}
return true;
}
function boolean updateGroup(GliderThermalQualityState a) {
a.samples++;
if ($in.0.vertical_speed != null) {
    integer band = thermalClass($in.0.vertical_speed);
    if (band > 0) {
        a.lift += $in.0.vertical_speed;
        a.usable++;
        if (band == 3) {
            a.strong++;
        }
    }
}
return false;
}
function integer transform(integer counter, GliderThermalQualityState a) {
if (counter > 0) {
    return SKIP;
}
$out.0.flight = $in.0.flight;
$out.0.sector = $in.0.sector;
$out.0.mean_lift = a.mean;
$out.0.quality = quality(a.strong, a.usable);
$out.0.total_samples = a.samples;
return ALL;
}
function void initGroup(GliderThermalQualityState a) {
a.lift = 0;
a.usable = 0;
a.strong = 0;
a.samples = 0;
}
```

