SpectralOccupancy operations: Emit exactly three histogram rows, numbered zero through two, for frequency bands below 10, from 10 through 19, and at least 20. Repeat the known and missing reading counts on each row. Group by receiver, polarization. Each complete key arrives contiguously; preserve input order.
Input 0:
<Record name="SpectralOccupancyInput" type="delimited"><Field name="receiver" type="integer" nullable="false"/><Field name="polarization" type="string" nullable="false"/><Field name="frequency" type="integer" nullable="true"/></Record>
Output 0:
<Record name="SpectralOccupancyOutput" type="delimited"><Field name="receiver" type="integer" nullable="false"/><Field name="polarization" type="string" nullable="false"/><Field name="band" type="integer" nullable="true"/><Field name="occupied" type="integer" nullable="true"/><Field name="unobserved" type="integer" nullable="true"/><Field name="known" type="integer" nullable="true"/></Record>
Accumulator:
<Record name="SpectralOccupancyState" type="delimited"><Field name="low" type="integer" nullable="true"/><Field name="middle" type="integer" nullable="true"/><Field name="high" type="integer" nullable="true"/><Field name="missing" type="integer" nullable="true"/><Field name="known" type="integer" nullable="true"/></Record>

```ctl
//#CTL2
function integer channelBand(integer frequency) {
    if (frequency < 10) {
        return 0;
    }
    if (frequency < 20) {
        return 1;
    }
    return 2;
}
function integer bandCount(integer band, integer low, integer middle, integer high) {
    if (band == 0) {
        return low;
    }
    if (band == 1) {
        return middle;
    }
    return high;
}
function integer transform(integer counter, SpectralOccupancyState a) {
if (counter >= 3) {
    return SKIP;
}
$out.0.receiver = $in.0.receiver;
$out.0.polarization = $in.0.polarization;
$out.0.band = counter;
$out.0.occupied = bandCount(counter, a.low, a.middle, a.high);
$out.0.unobserved = a.missing;
$out.0.known = a.known;
return ALL;
}
function void initGroup(SpectralOccupancyState a) {
a.low = 0;
a.middle = 0;
a.high = 0;
a.missing = 0;
a.known = 0;
}
function boolean updateGroup(SpectralOccupancyState a) {
if (isnull($in.0.frequency)) {
    a.missing++;
} else {
    a.known++;
    integer band = channelBand($in.0.frequency);
    switch (band) {
        case 0:
            a.low++;
            break;
        case 1:
            a.middle++;
            break;
        default:
            a.high++;
            break;
    }
}
return false;
}
function boolean finishGroup(SpectralOccupancyState a) {
return true;
}
