//#CTL2
string loyalty_2_source;
string[] loyalty_2_point_action_rows = [];
long[] loyalty_2_delta_rows = [];
long[] loyalty_2_remaining_rows = [];
date[] loyalty_2_valid_until_rows = [];
boolean[] loyalty_2_needs_review_rows = [];
function void stage_loyalty_2(string p0, long p1, long p2, date p3, boolean p4) {
    append(loyalty_2_point_action_rows, p0);
    append(loyalty_2_delta_rows, p1);
    append(loyalty_2_remaining_rows, p2);
    append(loyalty_2_valid_until_rows, p3);
    append(loyalty_2_needs_review_rows, p4);
}
function integer count() {
    loyalty_2_point_action_rows = [];
    loyalty_2_delta_rows = [];
    loyalty_2_remaining_rows = [];
    loyalty_2_valid_until_rows = [];
    loyalty_2_needs_review_rows = [];
    loyalty_2_source = $in.0.activity_id;
    /* Branch census:
       1. unknown member -> 1 rows
       2. cancelled activity -> 0 rows
       3. invalid movement -> 1 rows
       4. expired balance -> 3 rows
       5. insufficient points -> 1 rows
       6. reviewed bonus -> 3 rows
       7. simultaneous earn and spend -> 3 rows
       8. positive earning -> 1 rows
       9. remaining movement -> 1 rows
    */
    if ($in.0.member_token == null) {
        stage_loyalty_2("UNMATCHED", 0L, $in.0.balance, $in.0.expires_on, true);
        return 1; // unknown member
    }
    else if ($in.0.activity == "CANCEL") {
        return 0; // cancelled activity
    }
    else if ($in.0.earned < 0 || $in.0.redeemed < 0) {
        stage_loyalty_2("ERROR", 0L, $in.0.balance, $in.0.expires_on, true);
        return 1; // invalid movement
    }
    else if ($in.0.expires_on <= $in.0.as_of && $in.0.balance > 0L) {
        stage_loyalty_2("EXPIRE", -$in.0.balance, 0L, $in.0.expires_on, false);
        stage_loyalty_2("BALANCE", 0L, 0L, $in.0.expires_on, false);
        stage_loyalty_2("NOTICE", 0L, 0L, $in.0.expires_on, true);
        return 3; // expired balance
    }
    else if ($in.0.redeemed > $in.0.balance+$in.0.earned) {
        stage_loyalty_2("HOLD", 0L, $in.0.balance, $in.0.expires_on, true);
        return 1; // insufficient points
    }
    else if ($in.0.activity == "BONUS" && $in.0.review) {
        stage_loyalty_2("EARN", $in.0.earned, $in.0.balance+$in.0.earned, $in.0.expires_on, false);
        stage_loyalty_2("AUDIT", 0L, $in.0.balance+$in.0.earned, $in.0.expires_on, true);
        stage_loyalty_2("BONUS", $in.0.earned*4L, $in.0.balance+$in.0.earned*5L, $in.0.expires_on, false);
        return 3; // reviewed bonus
    }
    else if ($in.0.earned > 0 && $in.0.redeemed > 0) {
        stage_loyalty_2("EARN", $in.0.earned, $in.0.balance+$in.0.earned, $in.0.expires_on, false);
        stage_loyalty_2("SPEND", -$in.0.redeemed, $in.0.balance+$in.0.earned-$in.0.redeemed, $in.0.expires_on, false);
        stage_loyalty_2("BALANCE", 0L, $in.0.balance+$in.0.earned-$in.0.redeemed, $in.0.expires_on, false);
        return 3; // simultaneous earn and spend
    }
    else if ($in.0.earned > 0) {
        stage_loyalty_2("EARN", $in.0.earned, $in.0.balance+$in.0.earned, $in.0.expires_on, false);
        return 1; // positive earning
    }
    else if (true) {
        stage_loyalty_2("SPEND", -$in.0.redeemed, $in.0.balance-$in.0.redeemed, $in.0.expires_on, false);
        return 1; // remaining movement
    }
    return 0;
}
function integer transform(integer idx) {
    $out.0.source_activity_id = loyalty_2_source;
    $out.0.point_action = loyalty_2_point_action_rows[idx];
    $out.0.delta = loyalty_2_delta_rows[idx];
    $out.0.remaining = loyalty_2_remaining_rows[idx];
    $out.0.valid_until = loyalty_2_valid_until_rows[idx];
    $out.0.needs_review = loyalty_2_needs_review_rows[idx];
    return ALL;
}
