string[] time_0_pay_bucket_rows = [];
long[] time_0_minutes_rows = [];
date[] time_0_segment_from_rows = [];
date[] time_0_segment_to_rows = [];
boolean[] time_0_paid_rows = [];
long[] payroll_version_keys = [];
boolean[] payroll_opens = [];
long payroll_first_open;
