Develop ferry boarding group statistics. Use a Rollup grouped by sailing, with adjacent groups processed in input order. Input FerryObservation(sailing:string, manifest_ref:string, boarded_at:date, fare:decimal, traveller:string). Accumulator metadata is fixed at FerryAccumulator(sum_value:decimal, seen:integer); all metadata listed here is final. Output FerrySummary(sailing:string, first_ref:string, last_ref:string, first_year:integer, last_year:integer, accepted:integer, missing:integer, negative:integer, primary_count:integer, secondary_count:integer, minimum:decimal, maximum:decimal, total:decimal, mean_value:decimal, disposition:string, audit_text:string). Save the first and last manifest_ref (including null) and their UTC calendar years; a null timestamp yields a null year. Classify traveller into PRIMARY, SECONDARY or other. Exclude negative and null fare from accepted, min, max, total and mean; zero qualifies. Count missing and negative observations separately. The average is rounded to two places, null without accepted values. Disposition is EMPTY without accepted values, otherwise REVIEW when anything is missing or negative, else READY. Join every manifest_ref in encounter order with commas, substituting ? for null. Emit one summary per group, no intermediate rows.

```ctl
//#CTL2
string firstRef;
string lastRef;
integer firstYear;
integer lastYear;
integer acceptedCount;
integer missingCount;
integer negativeCount;
integer primaryCount;
integer secondaryCount;
decimal smallest;
decimal largest;
string auditText;
function void initGroup(FerryAccumulator acc) {
    acc.sum_value = 0D;
    acc.seen = 0;
    firstRef = null;
    lastRef = null;
    firstYear = null;
    lastYear = null;
    acceptedCount = 0;
    missingCount = 0;
    negativeCount = 0;
    primaryCount = 0;
    secondaryCount = 0;
    smallest = null;
    largest = null;
    auditText = "";
}
function boolean updateGroup(FerryAccumulator acc) {
    acc.seen++;
    if (acc.seen == 1) {
        firstRef = $in.0.manifest_ref;
        if ($in.0.boarded_at != null) {
            firstYear = getYear($in.0.boarded_at, "UTC");
        }
    }
    lastRef = $in.0.manifest_ref;
    if ($in.0.boarded_at == null) {
        lastYear = null;
    } else {
        lastYear = getYear($in.0.boarded_at, "UTC");
    }
    if ($in.0.traveller == "PRIMARY") {
        primaryCount++;
    } else if ($in.0.traveller == "SECONDARY") {
        secondaryCount++;
    }
    if ($in.0.fare == null) {
        missingCount++;
    } else if ($in.0.fare < 0D) {
        negativeCount++;
    } else {
        acceptedCount++;
        acc.sum_value = acc.sum_value + $in.0.fare;
        if (smallest == null || $in.0.fare < smallest) {
            smallest = $in.0.fare;
        }
        if (largest == null || $in.0.fare > largest) {
            largest = $in.0.fare;
        }
    }
    if (acc.seen > 1) {
        auditText = auditText + ",";
    }
    auditText = auditText + $in.0.manifest_ref;
    return false;
}
function integer updateTransform(integer counter, FerryAccumulator acc) {
    return SKIP;
}
function boolean finishGroup(FerryAccumulator acc) {
    return true;
}
function integer transform(integer counter, FerryAccumulator acc) {
    if (counter > 0) {
        return SKIP;
    }
    $out.0.sailing = $in.0.sailing;
    $out.0.first_ref = firstRef;
    $out.0.last_ref = lastRef;
    $out.0.first_year = firstYear;
    $out.0.last_year = lastYear;
    $out.0.accepted = acceptedCount;
    $out.0.missing = missingCount;
    $out.0.negative = negativeCount;
    $out.0.primary_count = primaryCount;
    $out.0.secondary_count = secondaryCount;
    $out.0.minimum = smallest;
    $out.0.maximum = largest;
    $out.0.total = acc.sum_value;
    if (acceptedCount == 0) {
        $out.0.mean_value = null;
        $out.0.disposition = "EMPTY";
    } else {
        $out.0.mean_value = round(acc.sum_value / acceptedCount, 2);
        if (missingCount + negativeCount > 0) {
            $out.0.disposition = "REVIEW";
        } else {
            $out.0.disposition = "READY";
        }
    }
    $out.0.audit_text = auditText;
    return ALL;
}
```

