Build the complete component script.

Charter departure: copy charter_id. Trim charter_text; null/empty is MISSING, an invalid strict yyyy-MM-dd date in UTC is INVALID, otherwise VALID with canonical yyyyMMdd. canonical is null unless valid. Use locale en.US. Normalize site by trim/uppercase. site_status is MISSING for blank, SHORT under three characters, OK otherwise. sequence_status is MISSING for null, INVALID at <=0, OK otherwise. copy_band is MISSING for null, INVALID at <=0, BATCH over 10, SINGLE at 1, SMALL otherwise. Null approved means false. Count one issue for non-VALID date, non-OK site, non-OK sequence, missing/invalid copies, and unapproved. Queue HOLD when any issue, BATCH for valid copies >10, READY otherwise.

Component: REFORMAT.
Input 0: {"name": "CharterInput", "type": "delimited", "fields": [{"name": "charter_id", "type": "integer"}, {"name": "charter_text", "type": "string"}, {"name": "site", "type": "string"}, {"name": "sequence_no", "type": "integer"}, {"name": "approved", "type": "boolean"}, {"name": "copies", "type": "integer"}]}
Output 0: {"name": "CharterResult", "type": "delimited", "fields": [{"name": "charter_id", "type": "integer"}, {"name": "status", "type": "string"}, {"name": "canonical", "type": "string"}, {"name": "site_key", "type": "string"}, {"name": "site_status", "type": "string"}, {"name": "sequence_status", "type": "string"}, {"name": "copy_band", "type": "string"}, {"name": "approved", "type": "boolean"}, {"name": "issues", "type": "integer"}, {"name": "queue", "type": "string"}]}

```ctl
//#CTL2
function integer transform() {
    $out.0.charter_id = $in.0.charter_id;
    string text = trim(nvl($in.0.charter_text, ""));
    $out.0.canonical = null;
    if (isEmpty(text)) {
        $out.0.status = "MISSING";
    } else if (!isDate(text, "yyyy-MM-dd", "en.US", "UTC", true)) {
        $out.0.status = "INVALID";
    } else {
        date parsed = str2date(text, "yyyy-MM-dd", "en.US", "UTC", true);
        $out.0.status = "VALID";
        $out.0.canonical = date2str(parsed, "yyyyMMdd", "en.US", "UTC");
    }
    integer issues = 0;
    if ($out.0.status != "VALID") {
        issues++;
    }
    $out.0.site_key = upperCase(trim(nvl($in.0.site, "")));
    if (isEmpty($out.0.site_key)) {
        $out.0.site_status = "MISSING";
        issues++;
    } else if (length($out.0.site_key) < 3) {
        $out.0.site_status = "SHORT";
        issues++;
    } else {
        $out.0.site_status = "OK";
    }
    if (isnull($in.0.sequence_no)) {
        $out.0.sequence_status = "MISSING";
        issues++;
    } else if ($in.0.sequence_no <= 0) {
        $out.0.sequence_status = "INVALID";
        issues++;
    } else {
        $out.0.sequence_status = "OK";
    }
    if (isnull($in.0.copies)) {
        $out.0.copy_band = "MISSING";
        issues++;
    } else if ($in.0.copies <= 0) {
        $out.0.copy_band = "INVALID";
        issues++;
    } else if ($in.0.copies > 10) {
        $out.0.copy_band = "BATCH";
    } else if ($in.0.copies == 1) {
        $out.0.copy_band = "SINGLE";
    } else {
        $out.0.copy_band = "SMALL";
    }
    $out.0.approved = $in.0.approved;
    if (!$out.0.approved) {
        issues++;
    }
    $out.0.issues = issues;
    if (issues > 0) {
        $out.0.queue = "HOLD";
    } else if ($in.0.copies > 10) {
        $out.0.queue = "BATCH";
    } else {
        $out.0.queue = "READY";
    }
    return ALL;
}
