Input 0: {"name": "SealInput", "type": "delimited", "fields": [{"name": "seal_id", "type": "integer"}, {"name": "seal_text", "type": "string"}, {"name": "quantity", "type": "integer"}, {"name": "priority", "type": "integer"}, {"name": "held", "type": "boolean"}, {"name": "destination", "type": "string"}, {"name": "operator_code", "type": "string"}]}
Output 0: {"name": "SealResult", "type": "delimited", "fields": [{"name": "seal_id", "type": "integer"}, {"name": "status", "type": "string"}, {"name": "normalized", "type": "string"}, {"name": "problems", "type": "integer"}, {"name": "route", "type": "string"}, {"name": "quantity_band", "type": "string"}, {"name": "priority_band", "type": "string"}, {"name": "destination_ok", "type": "boolean"}, {"name": "operator_ok", "type": "boolean"}, {"name": "held", "type": "boolean"}]}

