string firstRef;
string lastRef;
integer firstYear;
integer lastYear;
integer acceptedCount;
integer missingCount;
integer negativeCount;
integer primaryCount;
integer secondaryCount;
decimal smallest;
decimal largest;
string auditText;
function void initGroup(ArchiveAccumulator acc) {
    acc.sum_value = 0D;
    acc.seen = 0;
    firstRef = null;
    lastRef = null;
    firstYear = null;
    lastYear = null;
    acceptedCount = 0;
    missingCount = 0;
    negativeCount = 0;
    primaryCount = 0;
    secondaryCount = 0;
    smallest = null;
    largest = null;
    auditText = "";
}
function boolean updateGroup(ArchiveAccumulator acc) {
    acc.seen++;
    if (acc.seen == 1) {
        firstRef = $in.0.box_ref;
        if ($in.0.catalogued_at != null) {
            firstYear = getYear($in.0.catalogued_at, "UTC");
        }
    }
    lastRef = $in.0.box_ref;
    if ($in.0.catalogued_at == null) {
        lastYear = null;
    } else {
        lastYear = getYear($in.0.catalogued_at, "UTC");
    }
    if ($in.0.quality == "PRIMARY") {
        primaryCount++;
    } else if ($in.0.quality == "SECONDARY") {
        secondaryCount++;
    }
    if ($in.0.sheets == null) {
        missingCount++;
    } else if ($in.0.sheets < 0D) {
        negativeCount++;
    } else {
        acceptedCount++;
        acc.sum_value = acc.sum_value + $in.0.sheets;
        if (smallest == null || $in.0.sheets < smallest) {
            smallest = $in.0.sheets;
        }
        if (largest == null || $in.0.sheets > largest) {
            largest = $in.0.sheets;
        }
    }
    if (acc.seen > 1) {
        auditText = auditText + ",";
    }
    auditText = auditText + nvl($in.0.box_ref, "?");
    return false;
}
function integer updateTransform(integer counter, ArchiveAccumulator acc) {
    return SKIP;
}
function boolean finishGroup(ArchiveAccumulator acc) {
    return true;
}
function integer transform(integer counter, ArchiveAccumulator acc) {
    if (counter > 0) {
        return SKIP;
    }
    $out.0.ingest_lot = $in.0.ingest_lot;
    $out.0.first_ref = firstRef;
    $out.0.last_ref = lastRef;
    $out.0.first_year = firstYear;
    $out.0.last_year = lastYear;
    $out.0.accepted = acceptedCount;
    $out.0.missing = missingCount;
    $out.0.negative = negativeCount;
    $out.0.primary_count = primaryCount;
    $out.0.secondary_count = secondaryCount;
    $out.0.minimum = smallest;
    $out.0.maximum = largest;
    $out.0.total = acc.sum_value;
    if (acceptedCount == 0) {
        $out.0.mean_value = null;
        $out.0.disposition = "EMPTY";
    } else {
        $out.0.mean_value = round(acc.sum_value / acceptedCount, 2);
        if (missingCount + negativeCount > 0) {
            $out.0.disposition = "REVIEW";
        } else {
            $out.0.disposition = "READY";
        }
    }
    $out.0.audit_text = auditText;
    return ALL;
}
