prompt:
Validate this Reformat transform against its metadata and requirements.

Write CTL for this operational feed.

Badge activation: copy badge_id; trim badge_text; classify null or empty as MISSING, a whole-string mismatch to B[0-9]{5} as INVALID, otherwise VALID. Also output normalized trimmed uppercase text and held, treating null held as false. Count one problem each for non-VALID status, quantity null/nonpositive, priority null/outside 0..9, blank destination, operator code outside OP followed by three digits, and held. Route REVIEW if any problem, else EXPRESS at priority >=7, else STANDARD. Quantity band is UNKNOWN for null, EMPTY at <=0, BULK at >=100, SMALL otherwise. Priority band is UNKNOWN for null, INVALID outside 0..9, HIGH at >=7, NORMAL otherwise. destination_ok means nonblank; operator_ok uses that exact whole-string OP pattern.

Component: REFORMAT.
Input 0: {"name": "BadgeInput", "type": "delimited", "fields": [{"name": "badge_id", "type": "integer"}, {"name": "badge_text", "type": "string"}, {"name": "quantity", "type": "integer"}, {"name": "priority", "type": "integer"}, {"name": "held", "type": "boolean"}, {"name": "destination", "type": "string"}, {"name": "operator_code", "type": "string"}]}
Output 0: {"name": "BadgeResult", "type": "delimited", "fields": [{"name": "badge_id", "type": "integer"}, {"name": "status", "type": "string"}, {"name": "normalized", "type": "string"}, {"name": "problems", "type": "integer"}, {"name": "route", "type": "string"}, {"name": "quantity_band", "type": "string"}, {"name": "priority_band", "type": "string"}, {"name": "destination_ok", "type": "boolean"}, {"name": "operator_ok", "type": "boolean"}, {"name": "held", "type": "boolean"}]}

```ctl
//#CTL2
function integer transform() {
    string text = trim(nvl($in.0.badge_text, ""));
    $out.0.badge_id = $in.0.badge_id;
    if (isEmpty(text)) {
        $out.0.status = "MISSING";
    } else if (!(text ~= "B[0-9]{5}")) {
        $out.0.status = "INVALID";
    } else {
        $out.0.status = "VALID";
    }
    $out.0.normalized = upperCase(text);
    integer problems = 0;
    if ($out.0.status != "VALID") {
        problems++;
    }
    if (isnull($in.0.quantity)) {
        $out.0.quantity_band = "UNKNOWN";
        problems++;
    } else if ($in.0.quantity <= 0) {
        $out.0.quantity_band = "EMPTY";
        problems++;
    } else if ($in.0.quantity >= 100) {
        $out.0.quantity_band = "BULK";
    } else {
        $out.0.quantity_band = "SMALL";
    }
    if (isnull($in.0.priority)) {
        $out.0.priority_band = "UNKNOWN";
        problems++;
    } else if ($in.0.priority < 0 || $in.0.priority > 9) {
        $out.0.priority_band = "INVALID";
        problems++;
    } else if ($in.0.priority >= 7) {
        $out.0.priority_band = "HIGH";
    } else {
        $out.0.priority_band = "NORMAL";
    }
    $out.0.destination_ok = !isBlank(replace(nvl($in.0.destination, ""), "\\s", ""));
    if (!$out.0.destination_ok) {
        problems++;
    }
    string operatorText = nvl($in.0.operator_code, "");
    $out.0.operator_ok = operatorText ~= "OP[0-9]{3}";
    if (!$out.0.operator_ok) {
        problems++;
    }
    $out.0.held = nvl($in.0.held, false);
    if ($out.0.held) {
        problems++;
    }
    $out.0.problems = problems;
    if (problems > 0) {
        $out.0.route = "REVIEW";
    } else if ($in.0.priority >= 7) {
        $out.0.route = "EXPRESS";
    } else {
        $out.0.route = "STANDARD";
    }
    return ALL;
}
