//#CTL2
string time_0_source;
string[] time_0_pay_bucket_rows = [];
long[] time_0_minutes_rows = [];
date[] time_0_segment_from_rows = [];
date[] time_0_segment_to_rows = [];
boolean[] time_0_paid_rows = [];
long[] payroll_version_keys = [];
boolean[] payroll_opens = [];
long payroll_first_open;
long payroll_last_open;
long payroll_prior;
function void stage_time_0(string p0, long p1, date p2, date p3, boolean p4) {
    append(time_0_pay_bucket_rows, p0);
    append(time_0_minutes_rows, p1);
    append(time_0_segment_from_rows, p2);
    append(time_0_segment_to_rows, p3);
    append(time_0_paid_rows, p4);
    boolean opening = p0 == "TRAIN" || p0 == "OUTBOUND" || p0 == "ONSITE" || p0 == "RETURN" || p0 == "REGULAR" || p0 == "OVERTIME" || p0 == "WORK";
    long assigned_key = null;
    if (opening) {
        assigned_key = sequence(PayrollVersionSK, long).next();
        if (payroll_first_open == null) payroll_first_open = assigned_key;
        payroll_last_open = assigned_key;
    }
    append(payroll_version_keys, assigned_key);
    append(payroll_opens, opening);
}
function void resolve_payroll_links() {
    for (integer k = 0; k < length(time_0_pay_bucket_rows); k++) {
        if (time_0_pay_bucket_rows[k] == "AUDIT")
            payroll_version_keys[k] = payroll_first_open != null ? payroll_first_open : payroll_prior;
    }
}
function integer count() {
    payroll_version_keys = [];
    payroll_opens = [];
    payroll_first_open = null;
    payroll_last_open = null;
    payroll_prior = null;
    time_0_pay_bucket_rows = [];
    time_0_minutes_rows = [];
    time_0_segment_from_rows = [];
    time_0_segment_to_rows = [];
    time_0_paid_rows = [];
    time_0_source = $in.0.sheet_id;
    long duration = 0L;
    if (!isnull($in.0.clock_out)) duration = dateDiff($in.0.clock_out, $in.0.clock_in, minute);
    long pause = nvl($in.0.break_minutes, 0);
    long net = duration-pause;
    /* Branch census:
       1. unfinished attendance -> 1 rows
       2. withdrawn sheet -> 0 rows
       3. backward clock -> 1 rows
       4. approval pending -> 1 rows
       5. training attendance -> 1 rows
       6. three travel segments -> 3 rows
       7. overtime allocation -> 2 rows
       8. reviewed work -> 2 rows
       9. ordinary paid work -> 1 rows
    */
    if ($in.0.clock_out == null) {
        stage_time_0("OPEN", 0L, dateAdd($in.0.clock_in, 0L, minute), null, false);
        resolve_payroll_links();
        return 1; // unfinished attendance
    }
    else if ($in.0.category == "CANCEL") {
        resolve_payroll_links();
        return 0; // withdrawn sheet
    }
    else if (duration < 0L) {
        stage_time_0("ERROR", duration, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, duration, minute), false);
        resolve_payroll_links();
        return 1; // backward clock
    }
    else if (!$in.0.approved) {
        stage_time_0("PENDING", net, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, net, minute), false);
        resolve_payroll_links();
        return 1; // approval pending
    }
    else if ($in.0.category == "TRAIN") {
        stage_time_0("TRAIN", duration, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, duration, minute), true);
        resolve_payroll_links();
        return 1; // training attendance
    }
    else if ($in.0.category == "TRAVEL" && duration >= 120L) {
        stage_time_0("OUTBOUND", 60L, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, 60L, minute), true);
        stage_time_0("ONSITE", duration-120L, dateAdd($in.0.clock_in, 60L, minute), dateAdd($in.0.clock_in, duration-60L, minute), true);
        stage_time_0("RETURN", 60L, dateAdd($in.0.clock_in, duration-60L, minute), dateAdd($in.0.clock_in, duration, minute), true);
        resolve_payroll_links();
        return 3; // three travel segments
    }
    else if (net > 480L) {
        stage_time_0("REGULAR", 480L, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, 480L, minute), true);
        stage_time_0("OVERTIME", net-480L, dateAdd($in.0.clock_in, 480L, minute), dateAdd($in.0.clock_in, net, minute), true);
        resolve_payroll_links();
        return 2; // overtime allocation
    }
    else if ($in.0.review) {
        stage_time_0("AUDIT", 0L, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, 0L, minute), false);
        stage_time_0("WORK", net, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, net, minute), true);
        resolve_payroll_links();
        return 2; // reviewed work
    }
    else if (true) {
        stage_time_0("WORK", net, dateAdd($in.0.clock_in, 0L, minute), dateAdd($in.0.clock_in, net, minute), true);
        resolve_payroll_links();
        return 1; // ordinary paid work
    }
    resolve_payroll_links();
    return 0;
}
function integer transform(integer idx) {
    $out.0.source_sheet_id = time_0_source;
    $out.0.pay_bucket = time_0_pay_bucket_rows[idx];
    $out.0.minutes = time_0_minutes_rows[idx];
    $out.0.segment_from = time_0_segment_from_rows[idx];
    $out.0.segment_to = time_0_segment_to_rows[idx];
    $out.0.paid = time_0_paid_rows[idx];
    $out.0.version_key = payroll_version_keys[idx];
    $out.0.opens_version = payroll_opens[idx];
    return ALL;
}
