    $out.0.approved = nvl($in.0.approved, false);
    if (!$out.0.approved) {
        issues++;
    }
    $out.0.issues = issues;
    if (issues > 0) {
        $out.0.queue = "HOLD";
    } else if ($in.0.copies > 10) {
        $out.0.queue = "BATCH";
    } else {
        $out.0.queue = "READY";
    }
    return ALL;
}
