    collateral_actions = [];
    collateral_values = [];
    collateral_reference = $in.0.external_agreement_event_id;
    /* Priority table:
       1. closed agreement -> 0 rows
       2. bad collateral -> 1 rows
       3. within tolerance -> 0 rows
       4. novation -> 2 rows
       5. reviewed shortage -> 3 rows
       6. surplus release -> 1 rows
       7. unreviewed shortage -> 1 rows
       8. balanced agreement -> 1 rows
    */
    if ($in.0.instruction == "CLOSED") {
        return 0; // closed agreement
    }
    else if ($in.0.posted < 0d) {
        post_collateral("ERROR", -$in.0.posted);
