    }
    auditText = auditText + nvl($in.0.bag_tag, "?");
    return false;
}
function integer updateTransform(integer counter, LaundryAccumulator acc) {
    return SKIP;
}
function boolean finishGroup(LaundryAccumulator acc) {
    return true;
}
function integer transform(integer counter, LaundryAccumulator acc) {
    if (counter > 0) {
        return SKIP;
    }
    $out.0.wash_run = $in.0.wash_run;
    $out.0.first_ref = firstRef;
    $out.0.last_ref = lastRef;
    $out.0.first_year = firstYear;
    $out.0.last_year = lastYear;
    $out.0.accepted = acceptedCount;
    $out.0.missing = missingCount;
    $out.0.negative = negativeCount;
    $out.0.primary_count = primaryCount;
    $out.0.secondary_count = secondaryCount;
    $out.0.minimum = smallest;
    $out.0.maximum = largest;
    $out.0.total = acc.sum_value;
    if (acceptedCount == 0) {
        $out.0.mean_value = null;
        $out.0.disposition = "EMPTY";
    } else {
        $out.0.mean_value = round(acc.sum_value / acceptedCount, 2);
        if (missingCount + negativeCount > 0) {
            $out.0.disposition = "REVIEW";
        } else {
            $out.0.disposition = "READY";
        }
    }
    $out.0.audit_text = auditText;
    return ALL;
}
