    firstRef = null;
    lastRef = null;
    firstYear = null;
    lastYear = null;
    acceptedCount = 0;
    missingCount = 0;
    negativeCount = 0;
    primaryCount = 0;
    secondaryCount = 0;
    smallest = null;
    largest = null;
    auditText = "";
}
function boolean updateGroup(WeaveryAccumulator acc) {
    acc.seen++;
    if (acc.seen == 1) {
        firstRef = $in.0.spool_ref;
        if ($in.0.mounted_at != null) {
            firstYear = getYear($in.0.mounted_at, "UTC");
        }
    }
    lastRef = $in.0.spool_ref;
    if ($in.0.mounted_at == null) {
        lastYear = null;
    } else {
        lastYear = getYear($in.0.mounted_at, "UTC");
    }
    if ($in.0.fiber == "PRIMARY") {
        primaryCount++;
    } else if ($in.0.fiber == "SECONDARY") {
        secondaryCount++;
    }
    if ($in.0.thread_length == null) {
        missingCount++;
    } else if ($in.0.thread_length < 0D) {
        negativeCount++;
    } else {
        acceptedCount++;
        acc.sum_value = acc.sum_value + $in.0.thread_length;
        if (smallest == null || $in.0.thread_length < smallest) {
            smallest = $in.0.thread_length;
        }
        if (largest == null || $in.0.thread_length > largest) {
            largest = $in.0.thread_length;
        }
    }
    if (acc.seen > 1) {
        auditText = auditText + ",";
    }
    auditText = auditText + nvl($in.0.spool_ref, "?");
    return false;
}
function integer updateTransform(integer counter, WeaveryAccumulator acc) {
    return SKIP;
}
