       3. exact neutralization -> 0 rows
       4. certificate retirement -> 1 rows
       5. reviewed surplus -> 3 rows
       6. allowance breach -> 1 rows
       7. offset surplus -> 1 rows
       8. net liability -> 1 rows
    */
    if ($in.0.action == "DUP") {
        return 0; // duplicate certificate
    }
    else if ($in.0.offset < 0d) {
